# CP25 Step 7B reconstructed representative real-FCS gating atlas.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","figure_framework.R")); rp_install_and_load(c("dplyr","readr","tibble","ggplot2","patchwork","stringr"),"flowCore"); source(file.path(sd_repo_root(),"R","panels","CP25","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP25"); r<-file.path(a,"11_RData"); out<-file.path(a,"05_flow_figures_flowjo_style_TALL_LAYOUT"); dir.create(out,recursive=TRUE,showWarnings=FALSE); load(file.path(r,"SDY2583_CP25_STEP1_inventory_RECONSTRUCTED.RData")); load(file.path(r,"SDY2583_CP25_STEP4_composite_scores_RECONSTRUCTED.RData")); reps<-rp_select_representative_subjects(scored_data,CP25_MANIFEST$integrated_score); readr::write_csv(reps,file.path(out,"SDY2583_CP25_representative_samples_RECONSTRUCTED.csv")); plots<-list()
for(i in seq_len(nrow(reps))){sid<-reps$subject_id[i]; group<-as.character(reps$disease_group[i]); path<-fcs_files[grepl(paste0("^",sid,"_CP25"),basename(fcs_files))][1]; obj<-rp_read_transform(path); map<-obj$marker_map; ex<-flowCore::exprs(obj$ff); ch<-c(CD3=rp_find_channel(map,c("^CD3$"),"BV605-A"),CD4=rp_find_channel(map,c("^CD4$"),"PerCP-Cy5-5-A"),DUMP=rp_find_channel(map,c("Viability.*CD8.*CD13.*CD19.*TCR","dump"),"BV510-A"),CD25=rp_find_channel(map,c("^CD25$"),"BV421-A"),IL7RA=rp_find_channel(map,c("IL7RA","CD127"),"PE-A"),CD39=rp_find_channel(map,c("CD39"),"PE-Cy7-A"),ICOS=rp_find_channel(map,c("ICOS"),"BV650-A"),PD1=rp_find_channel(map,c("PD-?1"),"PE-CF594-A"),LAG3=rp_find_channel(map,c("LAG-?3"),"BV786-A")); raw<-rp_vec(ex,ch["CD3"])>2 & rp_vec(ex,ch["CD4"])>2; primary<-raw & rp_vec(ex,ch["DUMP"])<=1.5; treg<-primary & rp_vec(ex,ch["CD25"])>1.5 & rp_vec(ex,ch["IL7RA"])<=1.5
plots[[length(plots)+1]]<-rp_flow_density_plot(ex,ch["CD3"],ch["CD4"],2,2,paste(group,sid,"CD3/CD4")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[raw,,drop=FALSE],ch["CD4"],ch["DUMP"],2,1.5,paste(group,"dump-low")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[primary,,drop=FALSE],ch["IL7RA"],ch["CD25"],1.5,1.5,paste(group,"IL7RA/CD25")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[treg,,drop=FALSE],ch["CD39"],ch["ICOS"],1.5,1.5,paste(group,"CD39/ICOS in Treg-like")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[treg,,drop=FALSE],ch["PD1"],ch["LAG3"],1.5,1.5,paste(group,"PD-1/LAG-3 in Treg-like"))}
rp_save_flow_atlas(plots,file.path(out,"FigureS_CP25_representative_gating_RECONSTRUCTED.pdf"),ncol=2,width=9,height=20)
